function setupStick(){const stick=$('stick');const move=e=>{if(e.pointerId!==stickPointer)return;const r=stick.getBoundingClientRect(),x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2,l=Math.hypot(x,y),max=r.width*.34,mag=Math.min(l,max);touch.aim=l>7?Math.atan2(y,x):null;touch.thrust=l>7?Math.min(1,l/max):0;$('stick-knob').style.transform=`translate(${l?x/l*mag:0}px,${l?y/l*mag:0}px)`;};stick.addEventListener('pointerdown',e=>{if(panel||!started)return;e.preventDefault();stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);move(e);});stick.addEventListener('pointermove',move);const end=e=>{if(e.pointerId!==stickPointer)return;touch.aim=null;touch.thrust=0;stickPointer=null;$('stick-knob').style.transform='';};stick.addEventListener('pointerup',end);stick.addEventListener('pointercancel',end);stick.addEventListener('lostpointercapture',end);for(const b of document.querySelectorAll('[data-hold]')){b.addEventListener('pointerdown',e=>{if(panel||!started)return;e.preventDefault();b.setPointerCapture(e.pointerId);touch[b.dataset.hold]=true;b.classList.add('held');});const release=()=>{touch[b.dataset.hold]=false;b.classList.remove('held');};b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release);}}
window.addEventListener('blur',()=>{resetControls();save();});document.addEventListener('visibilitychange',()=>{resetControls();save();});window.addEventListener('pagehide',save);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
