canvas.addEventListener('pointerdown',e=>{if(panel||!started||game.s.docked)return;const p={x:(e.clientX-width/2)/cam.zoom+cam.x,y:(e.clientY-height/2)/cam.zoom+cam.y};const all=[game.station,...game.planets,...game.enemies,...game.asteroids];const target=all.filter(t=>dist(p,t)<Math.max(t.r,35/cam.zoom)).sort((a,b)=>dist(p,a)-dist(p,b))[0];if(target){game.target=target;game.auto=null;updateHUD();}});
