function drawMap(){const c=$('galaxy-map');if(!c)return;const box=c.getBoundingClientRect(),w=box.width,h=box.height;c.width=w*dpr;c.height=h*dpr;const cx=c.getContext('2d');cx.scale(dpr,dpr);cx.fillStyle='#08111b';cx.fillRect(0,0,w,h);const k=Math.min((w-55)/47,(h-75)/30),offsetX=w/2-20*k,offsetY=(h-20)/2-13.5*k;mapPoints=SYSTEMS.map(s=>({id:s.id,x:s.x*k+offsetX,y:s.y*k+offsetY}));cx.strokeStyle='#182a37';cx.lineWidth=1;for(let x=0;x<w;x+=28){cx.beginPath();cx.moveTo(x,0);cx.lineTo(x,h);cx.stroke();}for(let y=0;y<h;y+=28){cx.beginPath();cx.moveTo(0,y);cx.lineTo(w,y);cx.stroke();}const cur=mapPoints[game.s.system];cx.strokeStyle='#87e4d744';cx.fillStyle='#72c9be08';cx.beginPath();cx.arc(cur.x,cur.y,getStats(game.s).range*k,0,Math.PI*2);cx.fill();cx.stroke();for(const a of mapPoints){for(const b of mapPoints){if(a.id<b.id&&jumpDistance(a.id,b.id)<11){cx.strokeStyle='#3b5f7040';cx.beginPath();cx.moveTo(a.x,a.y);cx.lineTo(b.x,b.y);cx.stroke();}}}if(selectedSystem!==game.s.system){const to=mapPoints[selectedSystem];cx.setLineDash([4,5]);cx.strokeStyle='#eeab6c';cx.beginPath();cx.moveTo(cur.x,cur.y);cx.lineTo(to.x,to.y);cx.stroke();cx.setLineDash([]);}for(const p of mapPoints){const visited=game.s.visited.includes(p.id),selected=p.id===selectedSystem;cx.fillStyle=visited?'#90efdc':'#b5bcc7';cx.strokeStyle=selected?'#eeab6c':p.id===game.s.system?'#90efdc':'#345262';if(selected||p.id===game.s.system){cx.beginPath();cx.arc(p.x,p.y,11,0,6.28);cx.stroke();}cx.beginPath();cx.arc(p.x,p.y,p.id===game.s.system?4:3,0,6.28);cx.fill();cx.fillStyle=selected?'#f2c091':'#98aebc';cx.font='12px system-ui';cx.textAlign='center';if(w>450||selected||p.id===game.s.system)cx.fillText(SYSTEMS[p.id].name,p.x,p.y+22);}}
